      "content": "{\n  \"name\": \"pmp-dsh-tavern\",\n  \"version\": \"3.2.0\",\n  \"description\": \"A SillyTavern compatibility plugin that keeps DSH authoritative over sessions and execution, with frontend and backend APIs for composing Tavern capabilities with native DSH features.\",\n  \"type\": \"module\",\n  \"main\": \"packages/tavern-loader/src/bundle.js\",\n  \"exports\": {\n    \".\": \"./packages/tavern-loader/src/bundle.js\",\n    \"./format\": \"./packages/tavern-format/src/index.js\",\n    \"./loader\": \"./packages/tavern-loader/src/index.js\",\n    \"./world-book\": \"./packages/world-book/src/index.js\",\n    \"./world-book-library\": \"./packages/world-book-library/src/index.js\",\n    \"./preset\": \"./packages/preset/src/index.js\",\n    \"./character\": \"./packages/character/src/index.js\",\n    \"./user\": \"./packages/user/src/index.js\",\n    \"./trace\": \"./packages/tavern-trace/src/index.js\",\n    \"./session-template\": \"./packages/session-template/src/index.js\",\n    \"./client\": \"./dist/client.js\",\n    \"./identity\": \"./packages/identity.js\",\n    \"./package.json\": \"./package.json\",\n    \"./request-assembler\": \"./packages/request-assembler/index.js\",\n    \"./mvu\": \"./packages/mvu-adapter/src/index.js\",\n    \"./prompt-template\": \"./packages/prompt-template/index.js\",\n    \"./memory-sources\": \"./packages/memory-sources/index.js\",\n    \"./opening-worldbook\": \"./packages/opening-worldbook/index.js\",\n    \"./opening-worldbook/manifest\": \"./packages/opening-worldbook/manifest.js\",\n    \"./scope-catalog\": \"./packages/scope-catalog/index.js\",\n    \"./history-policy\": \"./packages/history-policy/index.js\",\n    \"./host\": \"./packages/tavern-loader/src/host.js\"\n  },\n  \"files\": [\n    \"screenshots.json\",\n    \"README_en.md\",\n    \"SECURITY.md\",\n    \"SECURITY_en.md\",\n    \"packages\",\n    \"dist\",\n    \"scripts\",\n    \"docs/assets\",\n    \"docs/OPERATION_LOGS.md\",\n    \"docs/OP