ent-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\",\n        \"@deepseek-ai/dsh-client-ui-chat\",\n        \"@deepseek-ai/dsh-client-ui-settings-general\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node build.mjs\",\n    \"test\": \"node --test\",\n    \"check\": \"npm run build && npm test\",\n    \"verify:2.0\": \"node scripts/verify-2.0.mjs && npm run build && npm run pack:check\",\n    \"pack:check\": \"npm pack --dry-run --cache .npm-cache\",\n    \"plugin:install\": \"node scripts/install.mjs\",\n    \"plugin:uninstall\": \"node scripts/uninstall.mjs\",\n    \"pack:release\": \"node scripts/pack-release.mjs\"\n  },\n  \"engines\": {\n    \"node\": \">=24.9.0\",\n    \"dsh\": \">=0.2.2-rc.1 <0.2.3-0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-util-crypto\": \"0.2.2-rc.1\",\n    \"dsh-prompt-assembler\": \"https://github.com/Player-MINEPIG/dsh-prompt-assembler/releases/download/v1.2.0/dsh-prompt-assembler-1.2.0.tgz\",\n    \"esbuild\": \"^0.28.2\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-util-crypto\": \">=0.2.2-rc.1 <0.2.3-0\",\n    \"dsh-prompt-assembler\": \"~1.2.0\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/Player-MINEPIG/dsh-tavern.git\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"dependencies\": {\n    \"@babel/standalone\": \"7.26.10\",\n    \"@jitl/quickjs-singlefile-browser-release-asyncify\": \"0.31.0\",\n    \"@jitl/quickjs-singlefile-browser-release-sync\": \"0.31.0\",\n    \"acorn\": \"8.15.0\",\n    \"acorn-jsx\": \"5.3.2\",\n    \"dompurify\": \"3.4.17\",\n    \"json5\": \"2.2.3\",\n    \"katex\": \"0.18.2\",\n    \"linkedom\": \"0.18.12\",\n    \"marked\": \"18.0.10\",\n    \"quickjs-emscripten-core\": \"0.31.0\",\n    \"yaml\": \"2.9.1\"\n  }\n}\n"
